#include <stdio.h>
#include <stdlib.h>
#include <string.h>

unsigned long long fib(int n) {
    unsigned long long a = 0, b = 1, c;
    int i;
    if (n == 0) return a;
    for (i = 2; i <= n; i++) {
        c = a + b;
        a = b;
        b = c;
    }
    return b;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s N\n", argv[0]);
        return 1;
    }
    int n = atoi(argv[1]);
    unsigned long long result = fib(n);
    printf("%llu\n", result);
    return 0;
}

